'use strict';
const eorServices=[
{name:'Recruitment',detail:'Once-off placement fee per hire',price:[300,400],once:true},
{name:'EOR & Payroll',detail:'Employment administration and payroll',price:[200,235]},
{name:'Power & Network Outage Kit',detail:'Backup power and connectivity',price:[100,120]},
{name:'IT Support & Security',detail:'Helpdesk, endpoint security and devices',price:[100,120]},
{name:'Premium Co-working Space',detail:'Optional desk access',price:[100,120]},
{name:'Full Hardware Provisioning',detail:'Laptop, monitors and peripherals',price:[100,120]},
{name:'Employee Wellness',detail:'Wellness activities and benefits support',price:[100,120]}];

const packages=[{name:'Core Hire',gbp:180,services:[1]},{name:'Core Tech',gbp:350,services:[1,3,5]},{name:'Core Platinum',gbp:580,services:[1,2,3,4,5,6]}];
const defaultState={version:8,region:'uk',eorCount:1,eorSelected:[1],packageIndex:null,roles:[]};let state=structuredClone(defaultState),attachedQuote='',customMessage='';
const allowedRoles=$$('[data-role]').map(el=>el.dataset.role);
function validateState(v){const s={...structuredClone(defaultState),...v};s.version=8;s.region=s.region==='usa'?'usa':'uk';s.eorCount=Math.round(num(s.eorCount,1,5000));s.eorSelected=Array.isArray(s.eorSelected)?[...new Set(s.eorSelected.filter(i=>Number.isInteger(i)&&i>=0&&i<7))]:[1];s.packageIndex=Number.isInteger(s.packageIndex)&&s.packageIndex>=0&&s.packageIndex<3?s.packageIndex:null;s.roles=Array.isArray(s.roles)?s.roles.filter(r=>allowedRoles.includes(r)):[];if(s.packageIndex!==null)s.eorSelected=[0,...packages[s.packageIndex].services];return s;}
try{const v=canRemember()?JSON.parse(localStorage.getItem('newclearus-scenario-v1')):null;if(v?.version===8)state=validateState(v);}catch{}
try{const v=new URLSearchParams(location.search).get('config');if(v)state=validateState(JSON.parse(v));}catch{}
function ix(){return state.region==='usa'?1:0;}
function money(v){return new Intl.NumberFormat(state.region==='usa'?'en-US':'en-GB',{style:'currency',currency:state.region==='usa'?'USD':'GBP',maximumFractionDigits:2}).format(v);}
function termLabel(){return '12-month contract · monthly billing';}
function save(){if(canRemember())try{localStorage.setItem('newclearus-scenario-v1',JSON.stringify(state));}catch{}}
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,3500);}
function toggleMenu(b){const open=$('mainnav').classList.toggle('open');b.setAttribute('aria-expanded',open);}
function closeMenu(){$('mainnav').classList.remove('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded','false');}
function setRegion(v){state.region=v==='usa'?'usa':'uk';$$('[data-region]').forEach(b=>{b.classList.toggle('active',b.dataset.region===state.region);b.setAttribute('aria-pressed',b.dataset.region===state.region);});$('market-note').textContent=state.region==='usa'?'USA · USD. Package conversions are indicative; final USD package rates are confirmed in your proposal.':'United Kingdom · GBP. All service fees exclude employee pay and statutory costs.';render();save();}
function eorServiceFee(i){return eorServices[i].price[ix()];}
function packageFee(i){return Math.round(packages[i].gbp*(state.region==='usa'?1.27:1)*100)/100;}
function eorTotal(){const active=state.eorSelected.filter(i=>!eorServices[i].once),sum=active.reduce((n,i)=>n+eorServiceFee(i),0);const fee=state.packageIndex===null?sum:packageFee(state.packageIndex);const once=state.eorSelected.includes(0)?eorServiceFee(0)*state.eorCount:0,total=Math.round(fee*state.eorCount*100)/100;return{count:state.eorCount,fee,total,once,annual:Math.round((total*12+once)*100)/100,contract:Math.round((total*12+once)*100)/100,active,sum};}
function line(label,value){return `<div class="line"><span>${esc(label)}</span><b>${value}</b></div>`;}
function render(){const e=eorTotal();$('eor-result-title').textContent=state.packageIndex===null?'Your monthly EOR fees':packages[state.packageIndex].name+' · monthly fees';$('eor-total').textContent=money(e.total);
$('eor-options').innerHTML=eorServices.map((o,i)=>`<label class="eor-service-option"><input type="checkbox" data-eor-service="${i}" ${state.eorSelected.includes(i)?'checked':''}><span>${o.name}<small>${o.detail}</small></span><span class="service-fee">${money(eorServiceFee(i))}<small>${o.once?'once off / hire':'/ employee / month'}</small></span></label>`).join('');
$$('[data-eor-service]').forEach(el=>el.addEventListener('change',()=>{const i=+el.dataset.eorService;state.packageIndex=null;state.eorSelected=state.eorSelected.filter(x=>x!==i);if(el.checked)state.eorSelected.push(i);render();document.querySelector('[data-eor-service="'+i+'"]')?.focus();save();}));
$('eor-selection-note').textContent=state.packageIndex===null?'Choose individual services or select a package below. All selections apply to each employee.':packages[state.packageIndex].name+' package pricing applies instead of adding the individual rates. Changing a checkbox switches to individual-service pricing.';
$('eor-breakdown').innerHTML=line('Monthly fee / employee',money(e.fee))+line('Employees',e.count)+(state.packageIndex===null?e.active.map(i=>line(eorServices[i].name,money(eorServiceFee(i)*e.count)+'/mo')).join(''):line('Package',packages[state.packageIndex].name))+line('Recruitment · once off',money(e.once))+line('12-month fees + recruitment',money(e.contract));
$('eor-empty-note').textContent=(state.region==='usa'&&state.packageIndex!==null?'Indicative USD package conversion at £1 = $1.27. ':'')+'Employee pay, statutory costs and taxes are separate. Totals assume the same staff count and services for the full 12 months.';
$('role-selection-note').textContent=state.roles.length?state.roles.length+' specialisms selected. Your EOR fees are unchanged.':'Your industry and hire level do not change the EOR fee.';
$('eor-prices').innerHTML=packages.map((p,i)=>`<article class="card ${state.packageIndex===i?'selected-package':''}"><span class="tag">12-MONTH CONTRACT</span><h4>${p.name}</h4><div class="price">${money(packageFee(i))}</div><span class="muted">/ employee / month${state.region==='usa'?' · indicative':''}</span><ul>${p.services.map(j=>'<li>'+eorServices[j].name+'</li>').join('')}</ul><p class="note">Recruitment: ${money(eorServiceFee(0))} once off per hire, charged separately. Employee pay, statutory costs and taxes excluded.</p><button class="btn" onclick="choosePackage(${i})">${state.packageIndex===i?'Selected':'Choose '+p.name}</button></article>`).join('');
$('package-currency-note').textContent=state.region==='usa'?'Package USD amounts use the existing planning conversion £1 = $1.27: not live FX or a confirmed USD contract rate. Individual service USD prices remain as listed.':'Core Hire £180 · Core Tech £350 · Core Platinum £580 per employee/month. Equipment specification and ownership are agreed in the contract.';refreshAttached();}
function choosePackage(i){state.packageIndex=i;state.eorSelected=[0,...packages[i].services];render();save();$('eor-builder').scrollIntoView({behavior:'smooth'});}
function estimateText(){const e=eorTotal();return `Remote team in South Africa: ${e.count} employees. ${termLabel()}.\n${state.packageIndex===null?'Individual services':packages[state.packageIndex].name}\nSelected services: ${state.eorSelected.map(i=>eorServices[i].name).join(', ')||'None'}.\n${money(e.fee)}/employee/month; ${money(e.total)}/month for your team.\nRecruitment once off: ${money(e.once)}. 12-month fees including recruitment: ${money(e.contract)}.\n${state.region==='usa'&&state.packageIndex!==null?'USD package amounts are indicative at £1 = $1.27; confirm in proposal.\n':''}Specialisms: ${state.roles.join(', ')||'To discuss'}.\nEmployee pay, statutory costs and taxes excluded. Totals assume unchanged headcount and services.`;}
function attachEstimate(kind,message=''){customMessage=message;attachedQuote=estimateText();refreshAttached();$('contact').scrollIntoView({behavior:'smooth'});}
function refreshAttached(){if(attachedQuote){attachedQuote=estimateText();$('quote-attached').hidden=false;$('quote-attached').textContent='Estimate attached: '+attachedQuote.split('\n')[0];}}
function enquiryText(){const f=$('contact-form');return `Name: ${f.elements.name.value}\nWork email: ${f.elements.email.value}\nMessage: ${f.elements.message.value}\n${customMessage}\n\n${estimateText()}`;}
$('contact-form').addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;location.href='mailto:joinus@newclearus.com?subject='+encodeURIComponent('Newclearus remote team enquiry')+'&body='+encodeURIComponent(enquiryText());$('form-status').textContent='Review and send the draft in your email app. Nothing is sent automatically.';});
$('copy-enquiry').addEventListener('click',async()=>{if(!$('contact-form').reportValidity())return;try{await navigator.clipboard.writeText(enquiryText());toast('Enquiry and estimate copied.');}catch{toast('Copy unavailable. Open the enquiry in your email app.');}});
$('eor-count').value=state.eorCount;$('eor-count').addEventListener('change',e=>{state.eorCount=Math.round(num(e.target.value,1,5000));e.target.value=state.eorCount;render();save();});
$$('[data-role]').forEach(el=>{el.checked=state.roles.includes(el.dataset.role);el.addEventListener('change',()=>{state.roles=$$('[data-role]').filter(e=>e.checked).map(e=>e.dataset.role);render();save();});});
$$('#mainnav a').forEach(a=>a.addEventListener('click',closeMenu));setRegion(state.region);if(!privacyChoice)$('cookie-consent').hidden=false;
